  stroke: black;
  stroke-width: 2;
  stroke-opacity: 1;
  fill-opacity: 1;
  stroke-linecap: round;
  stroke-linejoin: miter;
}

.svgbob text {
  white-space: pre;
  fill: black;
  font-family: Iosevka Fixed, monospace;
  font-size: 14px;
}

.svgbob rect.backdrop {
  stroke: none;
  fill: white;
}

.svgbob .broken {
  stroke-dasharray: 8;
}

.svgbob .filled {
  fill: black;
}

.svgbob .bg_filled {
  fill: white;
  stroke-width: 1;
}

.svgbob .nofill {
  fill: white;
}

.svgbob .end_marked_arrow {
  marker-end: url(#arrow);
}

.svgbob .start_marked_arrow {
  marker-start: url(#arrow);
}

.svgbob .end_marked_diamond {
  marker-end: url(#diamond);
}

.svgbob .start_marked_diamond {
  marker-start: url(#diamond);
}

.svgbob .end_marked_circle {
  marker-end: url(#circle);
}

.svgbob .start_marked_circle {
  marker-start: url(#circle);
}

.svgbob .end_marked_open_circle {
  marker-end: url(#open_circle);
}

.svgbob .start_marked_open_circle {
  marker-start: url(#open_circle);
}

.svgbob .end_marked_big_open_circle {
  marker-end: url(#big_open_circle);
}

.svgbob .start_marked_big_open_circle {
  marker-start: url(#big_open_circle);
}

</style>
  <defs>
    <marker id="arrow" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,0 0,4 4,2 0,0"></polygon>
    </marker>
    <marker id="diamond" viewBox="-2 -2 8 8" refX="4" refY="2" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <polygon points="0,2 2,0 4,2 2,4 0,2"></polygon>
    </marker>
    <marker id="circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="filled"></circle>
    </marker>
    <marker id="open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="2" class="bg_filled"></circle>
    </marker>
    <marker id="big_open_circle" viewBox="0 0 8 8" refX="4" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <circle cx="4" cy="4" r="3" class="bg_filled"></circle>
    </marker>
  </defs>
  <rect class="backdrop" x="0" y="0" width="{width}" height="{height}"></rect>
{body}
</svg>
'''

RECT_TEMPLATE = '  <rect x="{x}" y="{y}" width="{w}" height="{h}" class="solid nofill" rx="0"></rect>'


def unescape_string(s):
    # handle \n sequences
    return s.encode('utf-8').decode('unicode_escape')


def main(argv):
    if '-h' in argv or '--help' in argv:
        sys.stdout.write(HELP)
        return 0
    if '-V' in argv or '--version' in argv:
        sys.stdout.write(VERSION + "\n")
        return 0

    # parse output option
    out_file = None
    if '--output' in argv:
        try:
            idx = argv.index('--output')
            out_file = argv[idx+1]
        except Exception:
            out_file = None
    if '-o' in argv:
        try:
            idx = argv.index('-o')
            out_file = argv[idx+1]
        except Exception:
            pass

    # check -s flag
    inline = False
    if '-s' in argv:
        inline = True

    input_text = None
    # if inline, take first non-option argument
    if inline:
        # find first arg that does not start with - or is after -s
        # if -s is followed by a value, take that
        try:
            si = argv.index('-s')
            if si+1 < len(argv) and not argv[si+1].startswith('-'):
                input_text = argv[si+1]
        except ValueError:
            input_text = None
        if input_text is None:
            # fallback: take last arg
            for a in reversed(argv[1:]):
                if not a.startswith('-'):
                    input_text = a
                    break
        if input_text is None:
            # nothing: read stdin
            input_text = sys.stdin.read()
        else:
            input_text = unescape_string(input_text)
    else:
        # not inline: if there's a positional arg that's a file, read it
        pos = None
        for a in argv[1:]:
            if not a.startswith('-'):
                pos = a
                break
        if pos:
            try:
                with open(pos,'r',encoding='utf-8') as f:
                    input_text = f.read()
            except Exception:
                input_text = pos
        else:
            input_text = sys.stdin.read()

    # Now process text to produce simple svg
    lines = input_text.split('\n') if input_text is not None else ['']
    # remove possible trailing newline that creates empty last line? keep as-is
    # compute cols and rows
    cols = 0
    for l in lines:
        if len(l) > cols:
            cols = len(l)
    rows = len(lines)

    # find first/last non-space positions across entire text
    first_col = None
    last_col = None
    first_row = None
    last_row = None
    for ri, l in enumerate(lines):
        for ci, ch in enumerate(l):
            if ch != ' ' and ch != '\t':
                if first_col is None or ci < first_col:
                    first_col = ci
                if last_col is None or ci > last_col:
                    last_col = ci
                if first_row is None or ri < first_row:
                    first_row = ri
                if last_row is None or ri > last_row:
                    last_row = ri
    if first_col is None:
        first_col = 0
        last_col = 0
        first_row = 0
        last_row = 0

    # constants
    cw = 8
    rh = 16
    stroke = 2

    svg_width = cols * cw + stroke*4
    svg_height = rows * rh + stroke*8

    x = stroke*2 + first_col * cw
    y = stroke*4 + first_row * rh
    w = (last_col - first_col) * cw
    h = (last_row - first_row) * rh
    if w < 0: w = 0
    if h < 0: h = 0

    body = ''
    # crude detection: if input contains + and - and |, draw rect
    if '+' in input_text and ('-' in input_text or '|' in input_text):
        body = RECT_TEMPLATE.format(x=x, y=y, w=w, h=h) + '\n'

    svg = SVG_TEMPLATE.format(width=svg_width, height=svg_height, body=body)

    # write to out
    if out_file:
        with open(out_file,'w',encoding='utf-8') as f:
            f.write(svg)
    else:
        sys.stdout.write(svg)
    return 0

